<?php
namespace App\Http\Controllers; use App\Models\Chat; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Inertia\Inertia; use Inertia\Response; class ChatController extends Controller { public function room(string $room): Response { return Inertia::render('Chat/Room', ['room'=>$room,'messages'=>Chat::where('room_id',$room)->with('sender')->latest()->limit(50)->get()->reverse()->values()]); } public function store(Request $request, string $room): RedirectResponse { $data=$request->validate(['message'=>['nullable','string','max:5000'],'attachment'=>['nullable','file','max:20480']]); Chat::create(['room_id'=>$room,'sender_id'=>$request->user()->id,'message'=>$data['message']??null,'attachment_url'=>$request->file('attachment')?->store("chats/$room",'private')]); return back(); } }
